#!/usr/bin/env bash
# SPDX-License-Identifier: Apache-2.0
#
# Regenerate images.txt from the charts. Run from the repo root.
# The list is generated rather than maintained so it cannot drift.
#
# --check compares and REFUSES; it never writes. Same contract as
# gen-sbom.sh --check, so tools/check-all.sh can run it in parallel with
# everything else without touching the tree. The "# Generated by ... on DATE"
# line is ignored, because the date alone would make every day a diff.
set -euo pipefail
CHECK=0
case "${1:-}" in
  "") ;;
  --check) CHECK=1 ;;
  *) echo "usage: tools/gen-images.sh [--check]" >&2; exit 2 ;;
esac
# NOTE: a missing required value plus `2>/dev/null || true` once silently
# dropped the ENTIRE platform layer from this list. 14 images, all storage,
# ingress, LB and certs. Never swallow a render failure in a generator.
# Render values come from ci/values.yaml ... one file, same as CI, so a value
# added there is a value added here.
cd "$(dirname "$0")/.."
# The image extractor, shared with check-airgap.sh. See the header
# of that file. Prove it with `bash tools/lib/extract-images.sh --selftest`.
. "$(dirname "$0")/lib/extract-images.sh"

# WRITE TO A TEMP FILE AND MOVE ON SUCCESS. `{ ... } > images.txt` truncates the
# target BEFORE the block runs, so a render failure inside the loop leaves the
# file holding three comment lines and nothing else ... the script exits 1, but
# the damage is already done, and the zero-image guard at the bottom never runs
# because the `exit 1` in the loop fires first. Measured 2026-09-12: the AI layer
# failed to render during the version bump and images.txt lost 45 of 45 entries.
#
# images.txt is the air-gap mirror list. A truncated one that reaches a tag means
# an air-gapped install pulls nothing and fails very far from here.
# THE BUILT-IN FORGE'S IMAGE. Not a chart under charts/: `tockmox-install.sh
# bootstrap-forge` installs it beside Argo CD, so no render below can see it, and an
# air-gapped site that mirrors only what the charts render would find its forge unable
# to start. The pin lives in install/bootstrap-forge.sh and is read from there, so this
# list cannot say one thing while the installer pulls another. A missing or malformed
# pin is an error: never an empty line, never a silently shorter list.
forge_image_ref() {
  local repo tag
  repo=$(sed -n 's/^FORGE_IMAGE_REPO_DEFAULT="\([^"]*\)"$/\1/p' install/bootstrap-forge.sh)
  tag=$(sed -n 's/^FORGE_IMAGE_TAG_DEFAULT="\([^"]*\)"$/\1/p' install/bootstrap-forge.sh)
  if [ -z "$repo" ] || [ -z "$tag" ]; then
    echo "ERROR: install/bootstrap-forge.sh has no FORGE_IMAGE_REPO_DEFAULT / FORGE_IMAGE_TAG_DEFAULT pin" >&2
    exit 1
  fi
  # The chart's rootless variant: the chart appends the suffix itself unless told not to.
  echo "        image: ${repo}:${tag}-rootless"
  # The console's move Job (install/forge-move-template.sh), from the same file.
  local move
  move=$(sed -n 's/^MOVE_IMAGE_DEFAULT="\([^"]*\)"$/\1/p' install/bootstrap-forge.sh)
  if [ -z "$move" ]; then
    echo "ERROR: install/bootstrap-forge.sh has no MOVE_IMAGE_DEFAULT pin" >&2
    exit 1
  fi
  echo "        image: ${move}"
}
# THE IMAGES LONGHORN STARTS ITSELF. longhorn-manager creates the engine and
# instance-manager pods, the backing-image and support-bundle managers and the CSI
# driver (attacher, provisioner, resizer, snapshotter, node-driver-registrar,
# livenessprobe), naming each image in a container arg or an env value. No
# `image:` line in the render names them, so the extractor never saw them: until
# 2026-11-21 images.txt carried longhorn-manager, -share-manager and -ui only, and
# an air-gapped install could provision no Longhorn volume at all.
#
# DERIVED FROM THE VENDORED CHART, NOT TYPED. The set is every component under the
# vendored chart's own `image.longhorn` and `image.csi` values, with any
# tockmox-platform or CI override of `longhorn.image` laid over it, so a Longhorn
# bump that moves a tag or adds a component changes this list by itself, and
# `--check` fails until images.txt is regenerated. The registry is the one the
# chart's templates choose: global.imageRegistry, then privateRegistry.registryUrl,
# then global.cattle.systemDefaultRegistry, then the component's own registry,
# then docker.io. A component with no repository is left out: the only one is
# image.openshift.oauthProxy, which is empty unless a site runs OpenShift and is
# not under these two keys anyway. longhorn-cli, which Longhorn's own
# longhorn-images.txt also lists, is a client an operator runs by hand, not an
# image the cluster pulls, and the chart has no value for it.
#
# CROSS-CHECKED AGAINST THE RENDER. Every quoted longhornio reference in the
# rendered platform layer (the args and env values the manager reads) must be in
# the derived set. One that is not means Longhorn named an image somewhere this
# derivation does not read, and that is an error, never a shorter list.
longhorn_image_refs() {
  local render="$1" tgz
  tgz=$(ls charts/tockmox-platform/charts/longhorn-*.tgz 2>/dev/null || true)
  if [ -z "$tgz" ] || [ "$(printf '%s\n' "$tgz" | grep -c .)" -ne 1 ]; then
    echo "ERROR: expected exactly one vendored charts/tockmox-platform/charts/longhorn-*.tgz (run tools/helm-deps.sh), found: ${tgz:-none}" >&2
    exit 1
  fi
  if ! python3 -c 'import yaml' 2>/dev/null; then
    echo "ERROR: python3 with PyYAML is needed to read the vendored Longhorn chart's image values (tools/dev-env.sh provides it)" >&2
    exit 1
  fi
  local refs
  refs=$(helm show values "$tgz" | python3 -c '
import sys, yaml
chart = yaml.safe_load(sys.stdin) or {}
layers = [yaml.safe_load(open(f)) or {} for f in sys.argv[1:]]
def merge(a, b):
    if isinstance(a, dict) and isinstance(b, dict):
        out = dict(a)
        for k, v in b.items():
            out[k] = merge(a.get(k), v)
        return out
    return b if b is not None else a
lh = chart
glob = {}
for v in layers:
    lh = merge(lh, v.get("longhorn") or {})
    glob = merge(glob, v.get("global") or {})
g = merge(lh.get("global") or {}, glob)
common = g.get("imageRegistry") or (lh.get("privateRegistry") or {}).get("registryUrl") \
    or (g.get("cattle") or {}).get("systemDefaultRegistry") or ""
img = lh.get("image") or {}
n = 0
for section in ("longhorn", "csi"):
    for name, c in sorted((img.get(section) or {}).items()):
        if not isinstance(c, dict) or not c.get("repository"):
            continue
        if not c.get("tag"):
            sys.exit("ERROR: image.%s.%s in the vendored Longhorn chart has a repository and no tag" % (section, name))
        reg = common or c.get("registry") or "docker.io"
        print("%s/%s:%s" % (reg, c["repository"], c["tag"]))
        n += 1
if n == 0:
    sys.exit("ERROR: no image.longhorn / image.csi components in the vendored Longhorn chart")
' charts/tockmox-platform/values.yaml ci/values.yaml) || { echo "ERROR: could not derive Longhorn's images from $tgz" >&2; exit 1; }
  local seen missing
  seen=$(printf '%s\n' "$render" | grep -oE '"([^" ]*/)?longhornio/[^" ]+:[^" ]+"' | tr -d '"' | sort -u || true)
  missing=$(comm -23 <(printf '%s\n' "$seen" | sed '/^$/d') <(printf '%s\n' "$refs" | sort -u))
  if [ -n "$missing" ]; then
    echo "ERROR: the rendered Longhorn names images its chart values under image.longhorn / image.csi do not:" >&2
    printf '%s\n' "$missing" | sed 's/^/  /' >&2
    exit 1
  fi
  printf '%s\n' "$refs" | sed 's/^/        image: /'
}
OUT="$(mktemp "${TMPDIR:-/tmp}/tockmox-images.XXXXXX")"
trap 'rm -f "$OUT"' EXIT
{
  echo "# Container images referenced by Tockmox charts and the built-in forge."
  echo "# Generated by tools/gen-images.sh on $(date -u +%Y-%m-%d). Do not edit by hand."
  echo "#"
  { for c in charts/tockmox-*; do
    [ "$c" = "charts/tockmox-common" ] && continue
    helm dependency build "$c" >/dev/null 2>&1 || true
    # --skip-tests, and NOT --no-hooks. `helm template` renders hook resources
    # by default, which is correct for this list: the LiteLLM migration Job and
    # the Garage bootstrap and credentials Jobs are all hooks, they all really
    # deploy, and an airgap mirror that omits their images fails at install.
    #
    # TEST hooks are the exception. The LiteLLM subchart's two `helm test` pods
    # hardcode `image: busybox`, with no tag and no values override, and they
    # only ever run if somebody types `helm test`. Argo never does. Before this
    # flag, images.txt carried a bare `busybox` alongside a properly pinned
    # docker.io/library/busybox:1.38.0 ... so an operator mirroring the list
    # pulled `latest` for a code path that never executes, which is both
    # non-reproducible and the only unpinned entry in the file.
    #
    # --no-hooks would have fixed the symptom and dropped the three real Jobs
    # with it.
    r=$(helm template t "$c" \
      -f ci/values.yaml \
      --skip-tests) \
      || { echo "RENDER FAILED for $c" >&2; exit 1; }
    printf '%s\n' "$r"
    # Longhorn's own set, which no `image:` line names (longhorn_image_refs above).
    if [ "$c" = "charts/tockmox-platform" ]; then
      longhorn_image_refs "$r"
    fi
    # THE IDENTITY LAYER ONCE MORE WITH THE BUNDLED SERVER KEPT. From
    # 0.9.0 a default render runs Authentik on CNPG, so the bundled PostgreSQL
    # server and the pg_dump client drop out of it; an install that keeps the
    # bundled server (docs/deployment/upgrade.md) still pulls both, and an
    # air-gapped one can only pull what this list told it to mirror.
    if [ "$c" = "charts/tockmox-identity" ]; then
      helm template t "$c" \
        -f ci/values.yaml \
        --set identity.database.enabled=false --set authentik.postgresql.enabled=true \
        --skip-tests \
        || { echo "RENDER FAILED for $c with the bundled server kept" >&2; exit 1; }
    fi
  # ONE extractor, shared with check-airgap.sh (tools/lib/extract-images.sh,
  # ). It used to be a copy of that pipeline, and the copies had drifted:
  # this one used `\s`, which is a GNU extension that BSD `grep -E` ... the grep
  # on macOS ... does not honour. The gate that checks the mirror list and the
  # generator that writes it were not reading the same manifests, and on Linux
  # CI that was invisible. The quote handling and its reasoning now live in that
  # file, next to the self-test that proves it.
  done
  forge_image_ref
  } | extract_images
} > "$OUT"
# Both guards run BEFORE the move, so a bad result never reaches images.txt.
n=$(grep -cv '^#' "$OUT" || true)
[ "$n" -eq 0 ] && { echo "ERROR: zero images from nine implemented layers" >&2; exit 1; }
if [ "$CHECK" -eq 1 ]; then
  if diff <(grep -v '^# Generated' "$OUT") <(grep -v '^# Generated' images.txt) >&2; then
    echo "check-images: images.txt matches the charts ($n image(s))."
    exit 0
  fi
  echo "check-images: the committed images.txt does NOT match the charts. Run tools/gen-images.sh and commit the result." >&2
  exit 1
fi
mv "$OUT" images.txt
trap - EXIT
echo "images.txt written: $n image(s)"
exit 0
